import * as React from "react";
import { useLocation } from "@reach/router";
import { Link } from "gatsby";
import { useI18next, useTranslation } from "gatsby-plugin-react-i18next";
import navigationData from "../data/data.json";
import { saveLanguageSwitchScrollState } from "../utils/languageScroll";
import Logo from "./logo";

type MenuItemKey = "home" | "services" | "portfolio" | "about" | "contact";
type ServiceItem = { key: string; path: Record<string, string> };

const desktopServicesMenuId = "nav-services-drop";
const mobileMenuId = "nav-mobile";
const mobileServicesMenuId = "nav-mobile-services";

function normalizePath(path: string) {
  return path.replace(/\/+$/, "") || "/";
}

export default function Navigation() {
  const { t } = useTranslation();
  const { language, languages, changeLanguage } = useI18next();
  const location = useLocation();

  const [isOpen, setIsOpen] = React.useState(false);
  const [isServicesOpen, setIsServicesOpen] = React.useState(false);
  const [isServicesMobileOpen, setIsServicesMobileOpen] = React.useState(false);
  const [activeId, setActiveId] = React.useState<MenuItemKey | null>(null);

  const servicesRef = React.useRef<HTMLDivElement>(null);
  const rafRef = React.useRef<number | null>(null);

  const menuItems = navigationData.menu as MenuItemKey[];
  const servicesMenu = (navigationData.servicesMenu || []) as ServiceItem[];

  const homeHref = `/${language}/`;
  const servicesHubHref = `/${language}/services/`;
  const portfolioHref = `/${language}/portfolio/`;
  const aboutHref = `/${language}/about/`;
  const contactHref = `/${language}/contact/`;
  const legacyHref = `/${language}/selected-projects/`;

  const homePath = normalizePath(homeHref);
  const currentPath = normalizePath(location.pathname || homeHref);

  const isHomeRoute = currentPath === homePath;
  const isServicesRoute =
    currentPath === normalizePath(servicesHubHref) ||
    currentPath.startsWith(`${normalizePath(servicesHubHref)}/`);

  const hrefByItem: Record<MenuItemKey, string> = {
    home: homeHref,
    services: servicesHubHref,
    portfolio: portfolioHref,
    about: aboutHref,
    contact: contactHref,
  };

  const sectionItems = menuItems.filter(
    (item) => item !== "home" && item !== "portfolio" && item !== "about" && item !== "contact"
  );

  const itemIsActive = (item: MenuItemKey): boolean => {
    if (item === "home") return isHomeRoute && activeId === "home";
    if (item === "services") return isServicesRoute || activeId === "services";
    if (item === "portfolio")
      return currentPath === normalizePath(portfolioHref) || currentPath === normalizePath(legacyHref);
    if (item === "about") return currentPath === normalizePath(aboutHref);
    if (item === "contact") return currentPath === normalizePath(contactHref);
    return activeId === item;
  };

  const getServiceHref = (service: ServiceItem) => {
    const raw = service.path?.[language] || service.path?.en || "/";
    const cleaned = raw.replace(/^\/(en|fr)(?=\/)/, "");
    const withSlash = cleaned.startsWith("/") ? cleaned : `/${cleaned}`;
    return `/${language}${withSlash === "/" ? "" : withSlash}`;
  };

  const isServiceLinkActive = (href: string) => currentPath === normalizePath(href);

  const closeAllMenus = React.useCallback(() => {
    setIsOpen(false);
    setIsServicesOpen(false);
    setIsServicesMobileOpen(false);
  }, []);

  // Close on route change
  React.useEffect(() => { closeAllMenus(); }, [closeAllMenus, language, location.pathname]);

  // Scroll-spy on home
  React.useEffect(() => {
    if (!isHomeRoute) { setActiveId(null); return; }
    if (typeof window === "undefined") return;

    const sections = sectionItems
      .map((item) => document.getElementById(item))
      .filter((s): s is HTMLElement => Boolean(s));

    const update = () => {
      if (rafRef.current) return;
      rafRef.current = window.requestAnimationFrame(() => {
        rafRef.current = null;
        const offset = 140;
        let id: MenuItemKey = "home";
        sections.forEach((s) => {
          if (s.offsetTop <= window.scrollY + offset) id = s.id as MenuItemKey;
        });
        setActiveId(id);
      });
    };

    update();
    window.addEventListener("scroll", update, { passive: true });
    window.addEventListener("resize", update);
    return () => {
      window.removeEventListener("scroll", update);
      window.removeEventListener("resize", update);
      if (rafRef.current) window.cancelAnimationFrame(rafRef.current);
    };
  }, [isHomeRoute, sectionItems]);

  // Close dropdown on click outside / Escape
  React.useEffect(() => {
    if (!isServicesOpen) return;
    const onDown = (e: MouseEvent) => {
      if (servicesRef.current && !servicesRef.current.contains(e.target as Node))
        setIsServicesOpen(false);
    };
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") setIsServicesOpen(false); };
    document.addEventListener("mousedown", onDown);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("mousedown", onDown);
      document.removeEventListener("keydown", onKey);
    };
  }, [isServicesOpen]);

  return (
    <div className="topbar">
      <div className="topbar-inner shell">

        {/* Logo */}
        <Link to={homeHref} aria-label="Go to homepage" style={{ display: "flex", alignItems: "center" }}>
          <Logo color="fill-secondary" />
        </Link>

        {/* Desktop nav */}
        <nav className="nav" aria-label="Main navigation">
          {menuItems.map((item) => {
            if (item === "home") return null; // home handled by logo

            if (item === "services" && servicesMenu.length) {
              const isActive = itemIsActive(item);
              return (
                <div key={item} className="nav-item" ref={servicesRef}>
                  <button
                    type="button"
                    className={`nav-btn${isActive ? " active" : ""}`}
                    onClick={() => {
                      setActiveId("services");
                      setIsServicesOpen((v) => !v);
                    }}
                    aria-haspopup="true"
                    aria-expanded={isServicesOpen}
                    aria-controls={desktopServicesMenuId}
                  >
                    {t("menu.services")}
                    <span className="nav-chevron" aria-hidden="true">▾</span>
                  </button>

                  {isServicesOpen && (
                    <div id={desktopServicesMenuId} className="nav-drop" role="menu">
                      <div className="nav-drop-all">
                        <Link
                          to={servicesHubHref}
                          className={currentPath === normalizePath(servicesHubHref) ? "drop-active" : ""}
                          onClick={() => setIsServicesOpen(false)}
                          role="menuitem"
                        >
                          {t("menu.allServices")}
                        </Link>
                      </div>
                      {servicesMenu.map((service) => {
                        const href = getServiceHref(service);
                        return (
                          <Link
                            key={service.key}
                            to={href}
                            className={isServiceLinkActive(href) ? "drop-active" : ""}
                            onClick={() => setIsServicesOpen(false)}
                            role="menuitem"
                          >
                            {t(`services.${service.key}.h1`)}
                          </Link>
                        );
                      })}
                    </div>
                  )}
                </div>
              );
            }

            const href = hrefByItem[item];
            const isActive = itemIsActive(item);

            if (item === "portfolio" || item === "about" || item === "contact") {
              return (
                <Link
                  key={item}
                  to={href}
                  className={isActive ? "active" : ""}
                  onClick={() => setActiveId(item)}
                >
                  {t(`menu.${item}`)}
                </Link>
              );
            }

            return (
              <a key={item} href={href} className={isActive ? "active" : ""} onClick={() => setActiveId(item)}>
                {t(`menu.${item}`)}
              </a>
            );
          })}
        </nav>

        {/* Right: lang toggle + hamburger */}
        <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
          {/* Language toggle */}
          <div className="lang-toggle" role="group" aria-label="Language selector">
            {languages.map((lng) => (
              <button
                key={lng}
                type="button"
                className={lng === language ? "active" : ""}
                aria-current={lng === language ? "true" : undefined}
                aria-label={`Switch to ${lng.toUpperCase()}`}
                onClick={() => {
                  if (lng !== language) {
                    saveLanguageSwitchScrollState();
                    changeLanguage(lng);
                  }
                }}
              >
                {lng.toUpperCase()}
              </button>
            ))}
          </div>

          {/* Hamburger — mobile only */}
          <button
            type="button"
            className="nav-hamburger"
            onClick={() => setIsOpen((v) => !v)}
            aria-label={isOpen ? t("a11y.closeNavigation") as string : t("a11y.openNavigation") as string}
            aria-expanded={isOpen}
            aria-controls={mobileMenuId}
          >
            {isOpen ? "✕" : "☰"}
          </button>
        </div>
      </div>

      {/* Mobile menu */}
      {isOpen && (
        <div id={mobileMenuId} className="nav-mobile">
          {menuItems.map((item) => {
            if (item === "home") return null;

            if (item === "services" && servicesMenu.length) {
              const isActive = itemIsActive(item);
              return (
                <div key={item}>
                  <button
                    type="button"
                    className={`nav-mobile-link${isActive ? " active" : ""}`}
                    style={{ width: "100%", textAlign: "left", background: "none", border: 0, borderBottom: "1px solid var(--rule)", cursor: "none" }}
                    onClick={() => setIsServicesMobileOpen((v) => !v)}
                    aria-expanded={isServicesMobileOpen}
                    aria-controls={mobileServicesMenuId}
                  >
                    {t("menu.services")} {isServicesMobileOpen ? "▲" : "▾"}
                  </button>

                  {isServicesMobileOpen && (
                    <div id={mobileServicesMenuId} className="nav-mobile-sub">
                      <Link
                        to={servicesHubHref}
                        className={currentPath === normalizePath(servicesHubHref) ? "drop-active" : ""}
                        onClick={closeAllMenus}
                      >
                        {t("menu.allServices")}
                      </Link>
                      {servicesMenu.map((service) => {
                        const href = getServiceHref(service);
                        return (
                          <Link
                            key={service.key}
                            to={href}
                            className={isServiceLinkActive(href) ? "drop-active" : ""}
                            onClick={closeAllMenus}
                          >
                            {t(`services.${service.key}.h1`)}
                          </Link>
                        );
                      })}
                    </div>
                  )}
                </div>
              );
            }

            const href = hrefByItem[item];
            const isActive = itemIsActive(item);

            if (item === "portfolio" || item === "about" || item === "contact") {
              return (
                <Link
                  key={item}
                  to={href}
                  className={`nav-mobile-link${isActive ? " active" : ""}`}
                  onClick={() => { setActiveId(item); setIsOpen(false); }}
                >
                  {t(`menu.${item}`)}
                </Link>
              );
            }

            return (
              <a
                key={item}
                href={href}
                className={`nav-mobile-link${isActive ? " active" : ""}`}
                onClick={() => { setActiveId(item); setIsOpen(false); }}
              >
                {t(`menu.${item}`)}
              </a>
            );
          })}
        </div>
      )}
    </div>
  );
}
